import numpy as np
from scipy.optimize import fsolve

def solve_for_abc(a, b, c):
    lhs = (4*a)/(4*a**2 + 1) + (4*b)/(4*b**2 + 1) + (4*c)/(4*c**2 + 1)
    rhs = 1 / (2 * (a+b) * (b+c) * (c+a))
    return lhs - rhs

def find_solutions():
    solutions = []
    for a in np.linspace(0.01, 2, 100):
        for b in np.linspace(0.01, 2, 100):
            # For fixed a, b, we solve for c
            def target(c):
                if c <= 0: return 1e9
                return solve_for_abc(a, b, c)

            # Use a few guesses for c
            for guess in [0.1, 0.5, 1, 2, 5]:
                sol_c = fsolve(target, guess)
                if sol_c[0] > 0:
                    c = sol_c[0]
                    if abs(target(c)) < 1e-7:
                        solutions.append((a, b, c))
                        break
            if len(solutions) > 20: break
        if len(solutions) > 20: break
    return solutions

sols = find_solutions()
for s in sols:
    a, b, c = s
    print(f"a={a:.4f}, b={b:.4f}, c={c:.4f}, ab+bc+ca={a*b+b*c+c*a:.4f}")

import numpy as np
from scipy.optimize import fsolve

def equation(vars):
    a, b, c = vars
    if a <= 0 or b <= 0 or c <= 0:
        return [1e9, 1e9, 1e9]
    lhs = (4*a)/(4*a**2 + 1) + (4*b)/(4*b**2 + 1) + (4*c)/(4*c**2 + 1)
    rhs = 1 / (2 * (a+b) * (b+c) * (c+a))
    return [lhs - rhs, 0, 0]

def find_all_s2():
    s2_values = []
    for a in np.linspace(0.01, 2, 50):
        for b in np.linspace(0.01, 2, 50):
            def target(c):
                if c <= 0: return 1e9
                lhs = (4*a)/(4*a**2 + 1) + (4*b)/(4*b**2 + 1) + (4*c)/(4*c**2 + 1)
                rhs = 1 / (2 * (a+b) * (b+c) * (c+a))
                return lhs - rhs

            for guess in [0.1, 0.5, 1, 2, 5]:
                sol_c = fsolve(target, guess)
                if sol_c[0] > 0:
                    c = sol_c[0]
                    if abs(target(c)) < 1e-7:
                        s2_values.append(a*b + b*c + c*a)
                        break
    return s2_values

s2_vals = find_all_s2()
print(f"Unique s2 values: {np.unique(np.round(s2_vals, 4))}")
